<?php use MediaPitch\Core\Csrf; ?>
<section class="panel"><div class="panel-head"><div><h2>Reviews</h2><p>Editorial product reviews linked to the central catalog.</p></div><a class="primary-button" href="<?= e(url('admin/reviews/new')) ?>">+ New review</a></div><?php if(empty($reviews)):?><p class="muted">No reviews yet.</p><?php else:?><table class="data-table"><thead><tr><th>Title</th><th>Product</th><th>Score</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?= e($r['title']) ?></td><td><?= e($r['product_title'] ?? '—') ?></td><td><?= $r['score']!==null?e((string)$r['score']).'/10':'—' ?></td><td><?= e($r['status']) ?></td><td><a href="<?= e(url('admin/reviews/'.$r['id'].'/edit')) ?>">Edit</a> · <form method="post" action="<?= e(url('admin/reviews/'.(int)$r['id'].'/delete')) ?>" style="display:inline" onsubmit="return confirm('Permanently delete this review? This cannot be undone.')"><?= Csrf::field() ?><button type="submit" class="text-link" style="border:0;background:none;padding:0;cursor:pointer">Delete</button></form></td></tr><?php endforeach;?></tbody></table><?php endif;?></section>
